// pendingLogin is an ongoing CodeArts login.
type pendingLogin struct {
	// TicketID is generated by this plugin, used for both authorization links and subsequent ticket queries.
	//
	// It **must not** be overwritten by the ticket_id in the callback: the one in the portal callback is its own intermediate ticket,
	// querying it against the ticket API will result in an "invalid ticketId" error (observed TM.00001001).
	TicketID string
	// Secret is initially a self-generated value; replaced by the one issued by the portal once the browser callback is received.
	Secret string
	// TicketFallback indicates "portal secret is ready". Previously, querying the ticket API without it—using the self-generated
	// secret—would only continuously return invalid tickets and cause pointless polling.
	TicketFallback bool
	Verifier       string
	DPoPPrivateKey map[string]string
	// TicketURL is exclusively for unit tests to inject the ticket endpoint; empty means SnapManagerHost+EpLoginTicket.
	TicketURL string
}

// LoginStart initiates Huawei Cloud CodeArts authorization login.
func LoginStart(ctx context.Context, logins core.LoginSessions) (*pluginapi.AuthLoginStartResponse, error) {
	ticketID := core.RandomHex(16)
	secret := core.RandomHex(16)
	verifier, challenge, errPKCE := core.NewPKCEPair()
	if errPKCE != nil {
		return nil, fmt.Errorf("generate pkce: %w", errPKCE)
	}
	dpopJWK, err := generateDPoPJWK()
	if err != nil {
		return nil, fmt.Errorf("generate dpop jwk: %w", err)
	}

	sessionID := "codearts_" + core.RandomHex(8)
	logins.Register(VendorID, sessionID, 15*time.Minute, 0, &pendingLogin{
		TicketID:       ticketID,
		Secret:         secret,
		Verifier:       verifier,
		DPoPPrivateKey: dpopJWK,
	})

	return &pluginapi.AuthLoginStartResponse{
		Provider:  "freehub",
		URL:       buildAuthorizeURL(ticketID, challenge),
		State:     sessionID,
		ExpiresAt: time.Now().Add(15 * time.Minute),
	}, nil
}

// buildAuthorizeURL constructs the portal authorization link.
//
// Parameter set matches the official CodeArts Agent plugin (reversed from huaweicloud.authentication):
// The key is port — the portal uses it to construct the callback address http://127.0.0.1:<port>/oauth/callback.
// Without this parameter, the portal falls back to the default port, sending the callback to port 80 instead.
func buildAuthorizeURL(ticketID, challenge string) string {
	v := url.Values{}
	v.Set("theme", "2")
	v.Set("locale", "zh-cn")
	v.Set("uri_scheme", ClientID)
	v.Set("client_id", ClientID)
	v.Set("port", strconv.Itoa(LocalCallbackPort))
	v.Set("code_challenge", challenge)
	v.Set("code_challenge_method", "SHA-256")
	v.Set("ticket_id", ticketID)
	v.Set("plugin-name", PluginName)
	v.Set("plugin-version", PluginVersion)
	return PortalHost + "/authorize?" + v.Encode()
}

// LoginPoll polls the Huawei Cloud ticket login result.
func LoginPoll(ctx context.Context, logins core.LoginSessions, sessionID string) (*pluginapi.AuthLoginPollResponse, error) {
	session, pollState := logins.Poll(sessionID)
	if pollState == core.PollMissing {
		return &pluginapi.AuthLoginPollResponse{
			Status:  pluginapi.AuthLoginStatusError,
			Message: "Login session does not exist or has expired. Please re-initiate login and paste the callback link immediately after authorizing in the browser.",
		}, nil
	}
	pending, okPending := session.Data.(*pendingLogin)
	if !okPending {
		return &pluginapi.AuthLoginPollResponse{
			Status:  pluginapi.AuthLoginStatusError,
			Message: "Login session data is corrupted. Please re-initiate login.",
		}, nil
	}
	return pollLoginTicket(ctx, logins, sessionID, pending)
}

// pollLoginTicket exchanges the current ticket/secret in the session for a credential.
//
// ticket/secret will be replaced by SubmitCallback with "this plugin's ticket + portal's secret",
// so regular polling and pasting callbacks share this logic — the only difference is "where the secret comes from".
func pollLoginTicket(ctx context.Context, logins core.LoginSessions, sessionID string, pending *pendingLogin) (*pluginapi.AuthLoginPollResponse, error) {
	if !pending.TicketFallback {
		// The portal has not issued the secret yet: querying the ticket at this point will only return an "invalid ticketId",
		// not "user is logging in slowly". Separating these two wait states lets the user know what to do next.
		return &pluginapi.AuthLoginPollResponse{
			Status:  pluginapi.AuthLoginStatusPending,
			Message: "Waiting for browser to complete Huawei Cloud authorization… Once finished, please paste the callback link back into the console.",
		}, nil
	}

	ticketURL := strings.TrimSpace(pending.TicketURL)
	if ticketURL == "" {
		ticketURL = SnapManagerHost + EpLoginTicket
	}
	result, errFetch := fetchTicketCredentials(ctx, ticketURL, pending.TicketID, pending.Secret)
	if errFetch != nil {
		return nil, core.ToPluginError(errFetch)
	}
	if !result.Ready {
		message := "Waiting for the user to complete Huawei Cloud login in the new browser tab…"
		if result.Note != "" {
			message += " (Upstream: " + result.Note + ")"
		}
		return &pluginapi.AuthLoginPollResponse{Status: pluginapi.AuthLoginStatusPending, Message: message}, nil
	}

	logins.Delete(sessionID)
	return successResponse(result.Credentials, pending), nil
}

// successResponse converts the credentials returned by the ticket/token into a login success response recognized by the host.
func successResponse(creds *ticketCredentials, pending *pendingLogin) *pluginapi.AuthLoginPollResponse {
	uid := core.FirstNonEmpty(creds.UserID, creds.UserName, "codearts-user")
	cred := &Credential{
		Vendor:          VendorID,
		UserID:          creds.UserID,
		UserName:        creds.UserName,
		DomainID:        creds.DomainID,
		AccessKeyID:     creds.AccessKeyID,
		SecretAccessKey: creds.SecretAccessKey,
		SecurityToken:   creds.SecurityToken,
		RefreshToken:    creds.RefreshToken,
		CodeVerifier:    pending.Verifier,
		ClientID:        ClientID,
		DPoPPrivateKey:  pending.DPoPPrivateKey,
		Label:           "CodeArts-" + uid,
	}
	storageJSON, errStorage := cred.StorageJSON()
	if errStorage != nil {
		return &pluginapi.AuthLoginPollResponse{Status: pluginapi.AuthLoginStatusError, Message: errStorage.Error()}
	}
	return &pluginapi.AuthLoginPollResponse{
		Status:  pluginapi.AuthLoginStatusSuccess,
		Message: "Huawei Cloud account login successful",
		Auth: pluginapi.AuthData{
			Provider:    "freehub",
			FileName:    "codearts-" + uid + ".json",
			Label:       cred.Label,
			StorageJSON: storageJSON,
		},
	}
}

// ticketCredentials are temporary credentials returned by the login ticket or token API.
type ticketCredentials struct {
	UserName        string
	UserID          string
	DomainID        string
	RefreshToken    string
	AccessKeyID     string
	SecretAccessKey string
	SecurityToken   string
	Expiration      string
}

// ticketPollResult is the result of a ticket query.
type ticketPollResult struct {
	Credentials *ticketCredentials
	// Ready indicates that the upstream has issued usable AK/SK + security_token.
	Ready bool
	// Note is the upstream's original message (excluding tickets and keys), used to answer "where exactly it got stuck".
	Note string
}

// fetchTicketCredentials queries the login ticket using ticket/secret to exchange for AK/SK.
//
// Upstream consistently responds to unfinished authorizations with "not ready" (observed as TM.00001001 invalid ticketId,
// the same response as a randomly filled ticket), so here it is always treated as pending rather than a terminal failure —
// terminal failure is determined solely by session expiration, allowing the user to re-initiate.
func fetchTicketCredentials(ctx context.Context, ticketURL, ticketID, secret string) (ticketPollResult, error) {
	path := ticketURL + "?ticket_id=" + url.QueryEscape(ticketID) + "&secret=" + url.QueryEscape(secret)
	req, errReq := http.NewRequestWithContext(ctx, http.MethodGet, path, nil)
	if errReq != nil {
		return ticketPollResult{}, errReq
	}
	req.Header.Set("plugin-name", PluginName)
	req.Header.Set("plugin-version", PluginVersion)

	client := hostbridge.Client(ctx, 30*time.Second)
	resp, errDo := client.Do(req)
	if errDo != nil {
		return ticketPollResult{}, fmt.Errorf("poll login ticket failed: %w", errDo)
	}
	defer func() { _ = resp.Body.Close() }()

	body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if resp.StatusCode >= 400 {
		note := describeUpstream(resp.StatusCode, body)
		logger.Debug("codearts: ticket not ready %s", note)
		return ticketPollResult{Note: note}, nil
	}

	creds, errParse := decodeTokenResponse(body)
	if errParse != nil {
		return ticketPollResult{}, errParse
	}
	if creds.AccessKeyID == "" || creds.SecretAccessKey == "" || creds.SecurityToken == "" {
		return ticketPollResult{Note: describeUpstream(resp.StatusCode, body)}, nil
	}
	return ticketPollResult{Ready: true, Credentials: creds}, nil
}

// describeUpstream compresses the upstream response into a displayable sentence.
//
// Prefers the cloud vendor's standard error_code / error_msg; non-JSON bodies are truncated to 160 characters.
// The body contains no tickets or keys (those are request parameters) and can be safely displayed to the user.
func describeUpstream(status int, body []byte) string {
	var envelope struct {
		Code string `json:"error_code"`
		Msg  string `json:"error_msg"`
	}
	if err := json.Unmarshal(body, &envelope); err == nil && (envelope.Msg != "" || envelope.Code != "") {
		joined := core.FirstNonEmpty(envelope.Msg, envelope.Code)
		if envelope.Code != "" && envelope.Msg != "" {
			joined = envelope.Code + " " + envelope.Msg
		}
		return "HTTP " + strconv.Itoa(status) + " " + joined
	}
	trimmed := strings.TrimSpace(string(body))
	if len(trimmed) > 160 {
		trimmed = trimmed[:160] + "…"
	}
	if trimmed == "" {
		return "HTTP " + strconv.Itoa(status)
	}
	return "HTTP " + strconv.Itoa(status) + " " + trimmed
}

// CallbackInfo is the information brought back in the Huawei Cloud localhost callback.
type CallbackInfo struct {
	// TicketID is the ticket number carried by the URL in the callback (portal intermediate ticket, **not** this session's ticket).
	TicketID string
	// Secret is the ticket key issued by the portal: it must replace the self-generated secret of this session.
	Secret string
	// Code is the OAuth2 authorization code (included in newer portals; with it, the ticket channel can be bypassed).
	Code string
	// Redirect is the portal login page that the user will open in the browser next.
	Redirect string
}

// ParseCallback parses the localhost callback link pasted by the user.
//
// Two forms:
//
//	Old ticket channel: http://127.0.0.1:7866/oauth/callback?secret=<portal_key>&
//		redirect=<portal_login_page?...&ticket_id=<ticket_id>&...>
//
//	New authorization code channel: http://127.0.0.1:7866/oauth/callback?code=<auth_code>
//
// Only loopback addresses and this path are accepted: other addresses are not callbacks for this login, and wrong pastes should not alter the session state.
func ParseCallback(rawURL string) (*CallbackInfo, error) {
	rawURL = strings.TrimSpace(rawURL)
	if rawURL == "" {
		return nil, fmt.Errorf("empty callback url")
	}
	if !strings.HasPrefix(rawURL, "http") {
		rawURL = "http://127.0.0.1" + rawURL
	}
	u, err := url.Parse(rawURL)
	if err != nil {
		return nil, fmt.Errorf("parse callback url: %w", err)
	}
	if !strings.EqualFold(u.Scheme, "http") || !isLoopbackHost(u.Hostname()) || u.Path != LocalCallbackPath {
		return nil, fmt.Errorf("not a local callback address (should be http://127.0.0.1<port>%s)", LocalCallbackPath)
	}

	q := u.Query()
	info := &CallbackInfo{
		Code:     strings.TrimSpace(q.Get("code")),
		Secret:   strings.TrimSpace(q.Get("secret")),
		Redirect: strings.TrimSpace(q.Get("redirect")),
	}
	if info.Redirect != "" {
		if portal, errPortal := url.Parse(info.Redirect); errPortal == nil {
			info.TicketID = strings.TrimSpace(portal.Query().Get("ticket_id"))
		}
	}
	// Two available forms: authorization code, or "secret + portal login page".
	// When there is a secret but no redirect, the ticket ID cannot be verified and it cannot be claimed—better to let the user resend.
	if info.Code == "" && (info.Secret == "" || info.Redirect == "") {
		return nil, fmt.Errorf("callback link contains neither code nor secret + redirect")
	}
	return info, nil
}

// isLoopbackHost reports whether the host is a local loopback address.
func isLoopbackHost(host string) bool {
	if strings.EqualFold(strings.TrimSuffix(host, "."), "localhost") {
		return true
	}
	ip := net.ParseIP(host)
	return ip != nil && ip.IsLoopback()
}

// SubmitCallback accepts the localhost callback link pasted by the user.
//
// When the browser jumps back to 127.0.0.1, if the plugin and browser are not on the same machine (remote host / Docker /
// WSL), this callback cannot be received, and the login will stay waiting forever. The user pastes the entire link from the address bar back,
// and the login is completed right here:
//
//   - With code: directly exchange the authorization code for STS credentials in one step;
//   - With secret/redirect: record the secret issued by the portal (**keeping the ticket_id of this session itself**),
//     and check the ticket again; after the user clicks redirect to authorize, subsequent polling will exchange it for credentials.
func SubmitCallback(ctx context.Context, logins core.LoginSessions, state, rawURL string) (*core.CallbackSubmitResult, error) {
	sessionID := strings.TrimSpace(state)
	if sessionID == "" {
		return nil, core.NewPluginError("invalid_request", "missing login session state, please restart login", http.StatusBadRequest)
	}
	session, pollState := logins.Poll(sessionID)
	if pollState == core.PollMissing {
		return nil, core.NewPluginError("session_not_found",
			"login session does not exist or has expired, please restart login and paste the callback link immediately after browser authorization", http.StatusNotFound)
	}
	pending, okPending := session.Data.(*pendingLogin)
	if !okPending {
		return nil, core.NewPluginError("login_session_broken", "login session data is corrupted, please restart login", http.StatusBadRequest)
	}

	// Do not echo the original link when parsing fails: it contains the ticket key and authorization code.
	info, errParse := ParseCallback(rawURL)
	if errParse != nil {
		return nil, core.NewPluginError("callback_parse_failed",
			"failed to parse callback link, please ensure you pasted the complete link from the browser address bar (starting with local 127.0.0.1, path /oauth/callback)",
			http.StatusBadRequest)
	}

	if info.Code != "" {
		creds, errExchange := exchangeAuthorizationCode(ctx, info.Code, pending)
		if errExchange != nil {
			return nil, core.ToPluginError(errExchange)
		}
		logins.Delete(sessionID)
		polled := successResponse(creds, pending)
		return &core.CallbackSubmitResult{
			Status: polled.Status, Message: polled.Message, Auth: polled.Auth,
		}, nil
	}

	// Ticket channel: the portal secret is the valid one, while ticket_id still uses the one from this session.
	if info.TicketID != "" && pending.TicketID != "" && info.TicketID != pending.TicketID {
		return nil, core.NewPluginError("callback_mismatch",
			"the ticket ID in the callback link does not match the current login session, please restart login and re-authorize", http.StatusBadRequest)
	}
	pending.Secret = info.Secret
	pending.TicketFallback = true

	polled, errPoll := pollLoginTicket(ctx, logins, sessionID, pending)
	if errPoll != nil {
		return nil, core.ToPluginError(errPoll)
	}
	result := &core.CallbackSubmitResult{Status: polled.Status, Message: polled.Message}
	if polled.Status == pluginapi.AuthLoginStatusSuccess {
		result.Auth = polled.Auth
		return result, nil
	}
	// Ticket not yet exchanged for credentials: give the portal login page to the user to complete authorization, and the plugin continues polling.
	result.RedirectURL = info.Redirect
	return result, nil
}

// exchangeAuthorizationCode exchanges an OAuth2 authorization code for STS credentials.
func exchangeAuthorizationCode(ctx context.Context, code string, pending *pendingLogin) (*ticketCredentials, error) {
	form := url.Values{}
	form.Set("grant_type", "authorization_code")
	form.Set("client_id", ClientID)
	form.Set("code", code)
	form.Set("code_verifier", pending.Verifier)
	form.Set("redirect_uri", LocalCallbackURL)
	return requestTokenCredentials(ctx, form, pending.DPoPPrivateKey)
}

func generateDPoPJWK() (map[string]string, error) {
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, err
	}
	pad := func(b *big.Int, sz int) []byte {
		buf := make([]byte, sz)
		raw := b.Bytes()
		copy(buf[sz-len(raw):], raw)
		return buf
	}
	return map[string]string{
		"kty": "EC",
		"crv": "P-256",
		"x":   base64.RawURLEncoding.EncodeToString(pad(key.PublicKey.X, 32)),
		"y":   base64.RawURLEncoding.EncodeToString(pad(key.PublicKey.Y, 32)),
		"d":   base64.RawURLEncoding.EncodeToString(pad(key.D, 32)),
	}, nil
}

// requestTokenCredentials submits a form to the STS token endpoint (with DPoP proof) and parses the credentials.
//
// Exchanging an authorization code for a token and refreshing via refresh_token are two grant_types of the same endpoint, sharing this
// request and parsing logic: the DPoP private key is bound, and both channels must use the same one, otherwise upstream will reject.
func requestTokenCredentials(ctx context.Context, form url.Values, dpopJWK map[string]string) (*ticketCredentials, error) {
	tokenURL := STSHost + EpOAuthTokens
	proof, errProof := buildDPoPProof(dpopJWK, tokenURL)
	if errProof != nil {
		return nil, fmt.Errorf("build dpop proof: %w", errProof)
	}

	req, errReq := http.NewRequestWithContext(ctx, http.MethodPost, tokenURL, strings.NewReader(form.Encode()))
	if errReq != nil {
		return nil, errReq
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	req.Header.Set("DPoP", proof)

	client := hostbridge.Client(ctx, 30*time.Second)
	resp, errDo := client.Do(req)
	if errDo != nil {
		return nil, fmt.Errorf("token request failed: %w", errDo)
	}
	defer func() { _ = resp.Body.Close() }()

	body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if resp.StatusCode >= 400 {
		return nil, Classify(resp.StatusCode, string(body))
	}
	creds, errParse := decodeTokenResponse(body)
	if errParse != nil {
		return nil, errParse
	}
	if creds.AccessKeyID == "" || creds.SecretAccessKey == "" || creds.SecurityToken == "" {
		return nil, fmt.Errorf("token response missing credentials")
	}
	return creds, nil
}

// decodeTokenResponse parses the token/ticket response.
//
// The upstream has two field formats: the new channel uses credentials.{access_key_id, secret_access_key,
// security_token}, and the old ticket channel uses credential.{access, secret, securitytoken}.
// Both are recognized, otherwise credential fields would read empty after an upgrade.
func decodeTokenResponse(body []byte) (*ticketCredentials, error) {
	var res struct {
		UserName     string `json:"user_name"`
		UserID       string `json:"user_id"`
		DomainID     string `json:"domain_id"`
		RefreshToken string `json:"refresh_token"`
		Credential   struct {
			Access        string `json:"access"`
			Secret        string `json:"secret"`
			SecurityToken string `json:"securitytoken"`
			ExpiresAt     string `json:"expires_at"`
		} `json:"credential"`
		Credentials struct {
			AccessKeyID     string `json:"access_key_id"`
			SecretAccessKey string `json:"secret_access_key"`
			SecurityToken   string `json:"security_token"`
			Expiration      string `json:"expiration"`
		} `json:"credentials"`
	}
	if err := json.Unmarshal(body, &res); err != nil {
		return nil, fmt.Errorf("decode token response: %w", err)
	}
	return &ticketCredentials{
		UserName:        res.UserName,
		UserID:          res.UserID,
		DomainID:        res.DomainID,
		RefreshToken:    res.RefreshToken,
		AccessKeyID:     core.FirstNonEmpty(res.Credentials.AccessKeyID, res.Credential.Access),
		SecretAccessKey: core.FirstNonEmpty(res.Credentials.SecretAccessKey, res.Credential.Secret),
		SecurityToken:   core.FirstNonEmpty(res.Credentials.SecurityToken, res.Credential.SecurityToken),
		Expiration:      core.FirstNonEmpty(res.Credentials.Expiration, res.Credential.ExpiresAt),
	}, nil
}

// RefreshCredential exchanges a refresh_token for new STS credentials.
//
// The DPoP private key and refresh_token are bound: you must use the one that issued it, otherwise upstream reports
// InvalidDPoPHeader, which manifests as "credential invalid" and causes erroneous disablement.
func RefreshCredential(ctx context.Context, cred *Credential) (*Credential, bool, error) {
	if cred == nil || cred.RefreshToken == "" {
		return cred, false, nil
	}

	form := url.Values{}
	form.Set("grant_type", "refresh_token")
	form.Set("client_id", core.FirstNonEmpty(cred.ClientID, ClientID))
	form.Set("refresh_token", cred.RefreshToken)
	if cred.CodeVerifier != "" {
		form.Set("code_verifier", cred.CodeVerifier)
	}

	creds, errRefresh := requestTokenCredentials(ctx, form, cred.DPoPPrivateKey)
	if errRefresh != nil {
		return nil, false, errRefresh
	}

	updated := *cred
	updated.AccessKeyID = creds.AccessKeyID
	updated.SecretAccessKey = creds.SecretAccessKey
	updated.SecurityToken = creds.SecurityToken
	if creds.RefreshToken != "" {
		updated.RefreshToken = creds.RefreshToken
	}
	if creds.Expiration != "" {
		updated.Expiration = creds.Expiration
	}
	return &updated, true, nil
}

// MergeStorageJSON merges the renewal credentials.
func MergeStorageJSON(original []byte, updated *Credential) ([]byte, error) {
	if updated == nil {
		return original, nil
	}
	return core.MergeCredentialJSON(original, updated.StorageJSON, func(m map[string]any) {
		m["access_key_id"] = updated.AccessKeyID
		m["secret_access_key"] = updated.SecretAccessKey
		m["security_token"] = updated.SecurityToken
		if updated.RefreshToken != "" {
			m["refresh_token"] = updated.RefreshToken
		}
		if updated.Expiration != "" {
			m["expiration"] = updated.Expiration
		}
	})
}

func buildDPoPProof(jwk map[string]string, htu string) (string, error) {
	if jwk == nil || jwk["d"] == "" || jwk["x"] == "" || jwk["y"] == "" {
		return "", fmt.Errorf("missing dpop private key material")
	}

	xRaw, errX := base64.RawURLEncoding.DecodeString(jwk["x"])
	yRaw, errY := base64.RawURLEncoding.DecodeString(jwk["y"])
	dRaw, errD := base64.RawURLEncoding.DecodeString(jwk["d"])
	if errX != nil || errY != nil || errD != nil {
		return "", fmt.Errorf("decode dpop jwk base64 failed")
	}

	curve := elliptic.P256()
	privKey := &ecdsa.PrivateKey{
		PublicKey: ecdsa.PublicKey{
			Curve: curve,
			X:     new(big.Int).SetBytes(xRaw),
			Y:     new(big.Int).SetBytes(yRaw),
		},
		D: new(big.Int).SetBytes(dRaw),
	}

	header := map[string]any{
		"alg": "ES256",
		"typ": "dpop+jwt",
		"jwk": map[string]string{
			"kty": "EC",
			"crv": "P-256",
			"x":   jwk["x"],
			"y":   jwk["y"],
		},
	}
	headerJSON, _ := json.Marshal(header)

	b := make([]byte, 16)
	_, _ = rand.Read(b)
	jti := hex.EncodeToString(b)

	payload := map[string]any{
		"htm": "POST",
		"htu": htu,
		"iat": time.Now().Unix(),
		"jti": jti,
	}
	payloadJSON, _ := json.Marshal(payload)

	signingInput := base64.RawURLEncoding.EncodeToString(headerJSON) + "." + base64.RawURLEncoding.EncodeToString(payloadJSON)
	digest := sha256.Sum256([]byte(signingInput))

	r, s, errSign := ecdsa.Sign(rand.Reader, privKey, digest[:])
	if errSign != nil {
		return "", errSign
	}

	// Normalize to low S
	n := curve.Params().N
	halfN := new(big.Int).Rsh(n, 1)
	if s.Cmp(halfN) > 0 {
		s.Sub(n, s)
	}

	pad := func(val *big.Int) []byte {
		buf := make([]byte, 32)
		raw := val.Bytes()
		copy(buf[32-len(raw):], raw)
		return buf
	}

	sigBytes := append(pad(r), pad(s)...)
	return signingInput + "." + base64.RawURLEncoding.EncodeToString(sigBytes), nil
}
